function isSumOfTwoSquares(c: number): boolean {
  for (let a = 0; a * a <= c; a++) {
    const rest = c - a * a;
    const b = Math.round(Math.sqrt(rest));
    if (b * b === rest) return true;
  }
  return false;
}

