function isSumOfTwoSquares(c: number): boolean {
  let a = 0, b = Math.floor(Math.sqrt(c));
  while (b * b > c) b--; // guard against rounding up
  while (a <= b) {
    const s = a * a + b * b;
    if (s === c) return true;
    if (s < c) a++;
    else b--;
  }
  return false;
}

